def max_value_on_paths(N, grid_values):
    # Initialize the dp table with 0s
    dp = [[0] * N for _ in range(N)]

    # Loop through the grid values and populate the dp table
    for x, y, value in grid_values:
        dp[y][x] = value

    # Loop through the dp table and calculate the maximum sum of values on two paths
    max_sum = 0
    for y in range(N):
        for x in range(N):
            if dp[y][x] == 0:
                continue
            for y2 in range(y, N):
                for x2 in range(x, N):
                    max_sum = max(max_sum, dp[y][x] + dp[y2][x2])

    return max_sum

