def max_energy(beads):
    # Initialize a list to store the maximum energy for each subsequence of beads
    max_energies = [0] * len(beads)

    # Initialize a list to store the maximum energy for each bead
    bead_energies = [0] * len(beads)

    # Loop through each bead and compute its energy
    for i in range(len(beads)):
        bead_energies[i] = beads[i] * beads[(i + 1) % len(beads)]

    # Loop through each subsequence of beads and compute the maximum energy
    for i in range(len(beads)):
        for j in range(i + 1, len(beads)):
            max_energies[j] = max(max_energies[j], bead_energies[i] * bead_energies[j])

    # Return the maximum energy for the entire necklace
    return max(max_energies)

def polynomial_to_string(n, coeffs):
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        term = ""
        if coeff < 0:
            term += "-"
        elif coeff > 0 and i != 0:
            term += "+"
        if abs(coeff) != 1 or i == n:
            term += str(abs(coeff))
        if i == n:
            term += "x"
        else:
            term += "x^" + str(i + 1)
        terms.append(term)
    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(encoded)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        else:
            return "Failed"

    # Use the mapping to decode the message
    decoded = ""
    for letter in message:
        if letter in mapping:
            decoded += mapping[letter]
        else:
            return "Failed"

    return decoded

