def count_sequences(n: int, last: int, memo: dict) -> int:
    if n > last:
        return 0
    if n in memo:
        return memo[n]
    count = 0
    for i in range(1, last // 2 + 1):
        if n + i in memo:
            count += memo[n + i]
        else:
            count += count_sequences(n + i, last, memo)
    memo[n] = count
    return count

