def min_remaining_space(V, n, volumes):
    # Create a 2D array to store the maximum occupied volume for each subset of items
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Initialize the first row and column of the array
    for i in range(n + 1):
        dp[0][i] = 0
        dp[i][0] = V

    # Fill in the rest of the array using the dynamic programming approach
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if j < i:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + volumes[i - 1])

    # Return the difference between the box's total capacity and the maximum occupied volume
    return V - dp[n][n]

